  font-weight: 800;
}

.featured {
  min-height: 250px;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  overflow: hidden;
  margin-top: 28px;
  color: #fff;
  background: linear-gradient(135deg, #04295d, #0061a8 52%, #00a69a);
  border-radius: 28px;
  box-shadow: 0 22px 60px rgba(0, 88, 142, 0.18);
}

.featuredCopy {
  align-self: center;
  padding: 34px;
}

.featuredLabel {
