}

.featuredButton {
  display: inline-flex;
  margin-top: 20px;
  padding: 9px 14px;
  color: #06305c;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
  background: #fff;
  border-radius: 999px;
}

.featuredArt {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
