  background: radial-gradient(circle at center, rgba(255, 255, 255, 0.18), transparent 52%);
}

.featuredArt > span {
  width: 96px;
  height: 96px;
  display: grid;
  place-items: center;
  font-size: 48px;
  font-weight: 900;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 26px;
  backdrop-filter: blur(16px);
}

.featuredArt b {
  font-size: 10px;
  letter-spacing: 0.16em;
  color: rgba(255, 255, 255, 0.62);
}

.barcode {
  position: absolute;
  top: 25px;
  right: 35px;
  font-family: monospace;
  font-size: 17px;
  letter-spacing: -2px;
  color: rgba(255, 255, 255, 0.42);
  transform: rotate(8deg);
}

.appCount {
  color: #929298;
  font-size: 12px;
}

.filterBar {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 1px 1px 12px;
  scrollbar-width: none;
}

.filterBar::-webkit-scrollbar {
  display: none;
}

.filterChip {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 9px 13px;
  font: inherit;
  color: #4a4a50;
  font-size: 11px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid rgba(0, 0, 0, 0.07);
  border-radius: 999px;
  cursor: pointer;
}

.filterChipActive {
  color: #fff;
  background: #1c1c20;
  border-color: #1c1c20;
}

.appGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 13px;
}

.appCard {
  overflow: hidden;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba(0, 0, 0, 0.065);
  border-radius: 25px;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.05);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.appCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 46px rgba(0, 0, 0, 0.09);
}

.premiumCard {
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.96), rgba(246, 242, 255, 0.98));
  border-color: rgba(111, 74, 211, 0.15);
}

.appCardLink {
  display: block;
  padding: 18px;
  color: inherit;
  text-decoration: none;
}

.appTop {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.appIcon {
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  color: #fff;
  font-size: 25px;
  font-weight: 900;
  letter-spacing: -0.08em;
  border-radius: 19px;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.2), 0 10px 24px rgba(0, 0, 0, 0.15);
}

.appStatus {
  padding: 6px 9px;
  color: #74747a;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.09em;
  background: #f0f0f4;
  border-radius: 999px;
}

.appInfo {
  margin-top: 16px;
}

.appMeta {
  color: #8d8d93;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.appInfo h3 {
  margin: 4px 0 0;
  font-size: 19px;
  letter-spacing: -0.04em;
}

.appEnglish {
  margin: 2px 0 0;
  color: #9a9aa0;
  font-size: 10px;
}

.appTagline {
  min-height: 38px;
  margin: 9px 0 0;
  color: #5b5b60;
  font-size: 12px;
  line-height: 1.6;
}

.gadgetBadges {
  display: flex;
  gap: 6px;
  margin-top: 15px;
}

.gadgetBadge {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  font-size: 14px;
  filter: grayscale(1);
  opacity: 0.18;
  background: #f0f0f3;
  border-radius: 9px;
}

.gadgetBadgeOn {
  filter: none;
  opacity: 1;
  background: #f1f1f6;
}

.appBottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid #ececf0;
}

.appBottom span {
  color: #8f8f95;
  font-size: 10px;
}

.appBottom b {
  padding: 7px 13px;
  color: #0066cc;
  font-size: 11px;
  background: #eff1f5;
  border-radius: 999px;
}

.premiumBanner {
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr);
  gap: 20px;
  align-items: center;
  margin-top: 30px;
  padding: 26px;
  color: #fff;
  background: linear-gradient(135deg, #17111f, #33214d 52%, #5b2f78);
  border-radius: 28px;
}

.premiumOrb {
  width: 70px;
  height: 70px;
  display: grid;
  place-items: center;
  font-size: 28px;
  background: radial-gradient(circle at 35% 25%, #dfc7ff, #8a4fd0 56%, #3a1d62);
  border-radius: 22px;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.18);
}

.premiumBanner p {
  margin: 0;
  color: #d6b9ff;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.premiumBanner h2 {
  margin: 4px 0 6px;
  font-size: 20px;
  letter-spacing: -0.035em;
}

.premiumBanner span {
  color: rgba(255, 255, 255, 0.62);
  font-size: 11px;
  line-height: 1.7;
}

/* Existing live app wrapper */
.appFrame {
  min-height: 100vh;
  background: #f5f5f7;
}

.appBar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: grid;
  grid-template-columns: 130px minmax(0, 1fr) 130px;
  align-items: center;
  min-height: 64px;
  padding: 8px max(4vw, 16px);
  background: rgba(250, 250, 252, 0.9);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  backdrop-filter: blur(20px);
}

.appBack {
  color: #5362e8;
  font-size: 12px;
  font-weight: 750;
  text-decoration: none;
}

.appBarTitle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 0;
  font-size: 13px;
  font-weight: 800;
}

.appBarIcon {
  font-size: 18px;
}

.appBarSpacer {
  display: block;
}

.embedded {
  opacity: 0;
  transition: opacity 0.12s ease;
}

.embeddedReady {
  opacity: 1;
}

.embedded :global(main > header),
.embedded :global(main > div > section:first-of-type),
.embedded :global(section[aria-label="モジュールを選ぶ"]) {
  display: none;
}

.embedded :global(main) {
  min-height: calc(100vh - 64px);
}

.embedded :global(main > div) {
  padding-top: 24px;
}

/* Concept detail pages */
.conceptPage {
  min-height: 100vh;
  background: linear-gradient(180deg, #f6f6f9, #eceef4);
  color: #17171a;
}

.conceptShell {
  width: min(900px, calc(100% - 32px));
  margin: 0 auto;
  padding: 38px 0 80px;
}

.conceptHero {
  display: grid;
  grid-template-columns: 150px minmax(0, 1fr);
  gap: 28px;
