  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.conceptMetaRow b {
  padding: 4px 7px;
  color: #6f43c5;
  background: #f0e8ff;
  border-radius: 999px;
}

.conceptCopy h1 {
  margin: 8px 0 0;
  font-size: 34px;
  letter-spacing: -0.05em;
}

.conceptEnglish {
  margin: 2px 0 0;
  color: #9a9aa0;
  font-size: 11px;
}

.conceptTagline {
  margin: 12px 0 0;
  color: #55555a;
  font-size: 14px;
  line-height: 1.7;
}

.previewButton {
  margin-top: 18px;
  padding: 9px 16px;
  color: #77777c;
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  background: #ededf1;
  border: none;
  border-radius: 999px;
}

.conceptPanel {
  margin-top: 16px;
  padding: 24px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-radius: 24px;
}

.conceptPanel h2,
.premiumPlanPanel h2 {
  margin: 0;
  font-size: 18px;
  letter-spacing: -0.035em;
}

.conceptPanel > p {
  margin: 8px 0 0;
  color: #65656a;
  font-size: 12px;
  line-height: 1.8;
}

.highlightGrid,
.conceptDevices {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
  margin-top: 18px;
}

.highlightGrid span {
  padding: 13px;
  color: #47474d;
  font-size: 11px;
  font-weight: 700;
  text-align: center;
  background: #f3f3f7;
  border-radius: 13px;
}

.conceptDevice {
  padding: 16px;
  background: #f5f5f8;
  border-radius: 16px;
}

.conceptDevice > span {
  font-size: 27px;
}

.conceptDevice strong,
.conceptDevice small {
  display: block;
}

.conceptDevice strong {
  margin-top: 8px;
  font-size: 12px;
}

.conceptDevice small {
  margin-top: 4px;
  color: #85858a;
  font-size: 9px;
  line-height: 1.5;
}

.premiumPlanPanel {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr);
  gap: 16px;
  margin-top: 16px;
  padding: 24px;
  color: #fff;
  background: linear-gradient(135deg, #18101f, #4c246b);
  border-radius: 24px;
}

.premiumSpark {
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  font-size: 24px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 16px;
}

.premiumEyebrow {
  margin: 0 0 4px;
  color: #d6b9ff;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.premiumPlanPanel div > p:last-child {
  margin: 7px 0 0;
  color: rgba(255, 255, 255, 0.64);
  font-size: 11px;
  line-height: 1.7;
}

@media (max-width: 760px) {
  .storeShell {
    width: min(100% - 24px, 1040px);
    padding-top: 18px;
  }

  .hero {
    min-height: 360px;
    padding: 26px 22px;
    border-radius: 27px;
  }

  .deviceGrid {
    display: flex;
    overflow-x: auto;
    padding-bottom: 4px;
    scrollbar-width: none;
  }

  .deviceCard {
    min-width: 235px;
  }

  .featured {
    grid-template-columns: 1fr;
  }

  .featuredArt {
    min-height: 170px;
  }

  .appGrid {
    grid-template-columns: 1fr;
  }

  .appTagline {
    min-height: auto;
  }

  .appBar {
    grid-template-columns: 105px minmax(0, 1fr) 105px;
  }

  .conceptHero {
    grid-template-columns: 92px minmax(0, 1fr);
    gap: 18px;
    padding: 20px;
  }

  .conceptIcon {
    width: 92px;
    height: 92px;
    font-size: 30px;
    border-radius: 24px;
  }

  .conceptCopy h1 {
    font-size: 25px;
  }

  .highlightGrid,
  .conceptDevices {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .storeHeader {
    padding-left: 14px;
    padding-right: 14px;
  }

  .brandBlock small,
  .toolsLink {
    display: none;
  }

  .hero h1 {
    font-size: 39px;
  }

  .heroDevices {
    gap: 6px;
  }

  .heroDevice {
    padding: 8px 10px;
    font-size: 10px;
  }

  .featuredCopy {
    padding: 25px 20px;
  }

  .premiumBanner {
    grid-template-columns: 50px minmax(0, 1fr);
    gap: 14px;
    padding: 20px;
  }

  .premiumOrb {
    width: 50px;
    height: 50px;
    border-radius: 15px;
  }

  .premiumBanner h2 {
    font-size: 17px;
  }

  .appBar {
    grid-template-columns: 85px minmax(0, 1fr) 85px;
  }

  .appBack {
    font-size: 10px;
  }

  .conceptShell {
    width: min(100% - 20px, 900px);
    padding-top: 18px;
  }

  .conceptHero {
    grid-template-columns: 1fr;
  }
}

.page {
