"use client";

import { useMemo, useSyncExternalStore } from "react";
import type { CSSProperties } from "react";
import styles from "./levelup.module.css";

type LevelUpGame = {
  id: string;
  title: string;
  kicker: string;
  skill: string;
  description: string;
  icon: string;
  accent: string;
  accentSoft: string;
  href: string;
};

type LevelUpCatalogGridProps = {
  games: LevelUpGame[];
  updateCounts: Record<string, number>;
};

const FAVORITES_STORAGE_KEY = "hitobito-levelup-favorites-v1";
const FAVORITES_CHANGE_EVENT = "hitobito-levelup-favorites-change";
const EMPTY_FAVORITES = "[]";

function getFavoritesSnapshot() {
  try {
    return window.localStorage.getItem(FAVORITES_STORAGE_KEY) ?? EMPTY_FAVORITES;
  } catch {
    return EMPTY_FAVORITES;
  }
}

function getServerFavoritesSnapshot() {
  return EMPTY_FAVORITES;
}

function subscribeFavorites(onStoreChange: () => void) {
  const handleStorage = (event: StorageEvent) => {
    if (event.key === FAVORITES_STORAGE_KEY) onStoreChange();
  };
  const handleLocalChange = () => onStoreChange();

  window.addEventListener("storage", handleStorage);
  window.addEventListener(FAVORITES_CHANGE_EVENT, handleLocalChange);

  return () => {
    window.removeEventListener("storage", handleStorage);
    window.removeEventListener(FAVORITES_CHANGE_EVENT, handleLocalChange);
  };
}

function parseFavorites(snapshot: string): Set<string> {
  try {
    const parsed: unknown = JSON.parse(snapshot);
    if (!Array.isArray(parsed)) return new Set();
    return new Set(parsed.filter((value): value is string => typeof value === "string"));
  } catch {
    return new Set();
  }
}

export default function LevelUpCatalogGrid({ games, updateCounts }: LevelUpCatalogGridProps) {
  const favoritesSnapshot = useSyncExternalStore(
    subscribeFavorites,
    getFavoritesSnapshot,
    getServerFavoritesSnapshot,
  );
  const favorites = useMemo(() => parseFavorites(favoritesSnapshot), [favoritesSnapshot]);

  const orderedGames = useMemo(() => {
    const originalOrder = new Map(games.map((game, index) => [game.id, index]));
    return [...games].sort((a, b) => {
      const favoriteDifference = Number(favorites.has(b.id)) - Number(favorites.has(a.id));
      if (favoriteDifference !== 0) return favoriteDifference;
      const updateDifference = (updateCounts[b.id] ?? 1) - (updateCounts[a.id] ?? 1);
      if (updateDifference !== 0) return updateDifference;
      return (originalOrder.get(a.id) ?? 0) - (originalOrder.get(b.id) ?? 0);
    });
  }, [games, favorites, updateCounts]);

  const toggleFavorite = (gameId: string) => {
    const next = new Set(favorites);
    if (next.has(gameId)) next.delete(gameId);
    else next.add(gameId);

    const serialized = JSON.stringify([...next]);
    try {
      window.localStorage.setItem(FAVORITES_STORAGE_KEY, serialized);
    } catch {
      // Keep the current session working even when browser storage is unavailable.
    }

    window.dispatchEvent(new Event(FAVORITES_CHANGE_EVENT));
  };

  return (
    <div className={styles.grid}>
      {orderedGames.map((game, index) => {
        const isFavorite = favorites.has(game.id);
        const cardStyle = {
          "--accent": game.accent,
          "--accent-soft": game.accentSoft,
        } as CSSProperties;

        return (
          <article className={styles.cardShell} id={game.id} key={game.id} style={cardStyle}>
            <a className={styles.card} href={game.href} aria-label={`${game.title}を遊ぶ`}>
              <div className={styles.cardTop}>
                <span className={styles.number}>{String(index + 1).padStart(2, "0")}</span>
                <span className={styles.status}>UPDATE ×{updateCounts[game.id] ?? 1}</span>
              </div>
              <div className={styles.symbol} aria-hidden="true">
                {game.icon}
              </div>
              <div className={styles.cardCopy}>
                <h3
                  style={{
                    marginBottom: 0,
                    fontSize: "clamp(25px, 2.6vw, 36px)",
                    lineHeight: 1.08,
                    letterSpacing: "-0.045em",
                  }}
                >
                  {game.title}
                </h3>
                <p
                  style={{
                    margin: "16px 0 0",
                    color: game.accent,
                    fontSize: "13px",
                    lineHeight: 1.65,
                    fontWeight: 850,
                  }}
                >
                  {game.description}
                </p>
              </div>
            </a>
            <button
              className={`${styles.favoriteButton} ${isFavorite ? styles.favoriteActive : ""}`}
              type="button"
              aria-label={`${game.title}を${isFavorite ? "お気に入りから外す" : "お気に入りに追加"}`}
              aria-pressed={isFavorite}
              title={isFavorite ? "お気に入りから外す" : "お気に入りに追加"}
              onClick={() => toggleFavorite(game.id)}
            >
              <span aria-hidden="true">{isFavorite ? "★" : "☆"}</span>
            </button>
          </article>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import LevelUpHomeButton from "../../../components/LevelUpHomeButton";
import styles from "./angerReply.module.css";

type Scene =
  | "opening"
  | "shrink"
  | "tiny"
  | "timer"
  | "purpose"
  | "correction"
  | "respect"
  | "discharge"
  | "last"
  | "finish"
  | "send-anyway";

type Stats = {
  sessions: number;
  pauses: number;
  avoidedNowSend: number;
};

const STORAGE_KEY = "levelup-negotiator-anger-reply-v1";
const EMPTY_STATS: Stats = { sessions: 0, pauses: 0, avoidedNowSend: 0 };

function loadStats(): Stats {
  if (typeof window === "undefined") return EMPTY_STATS;
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return EMPTY_STATS;
    const parsed = JSON.parse(raw) as Partial<Stats>;
    return {
      sessions: Number(parsed.sessions) || 0,
      pauses: Number(parsed.pauses) || 0,
      avoidedNowSend: Number(parsed.avoidedNowSend) || 0,
    };
  } catch {
    return EMPTY_STATS;
  }
}

function buzz(pattern: number | number[] = 20) {
  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    navigator.vibrate(pattern);
  }
}

export default function AngerReplyGame() {
  const [scene, setScene] = useState<Scene>("opening");
  const [pressure, setPressure] = useState(100);
  const [pauseSeconds, setPauseSeconds] = useState(0);
  const [timer, setTimer] = useState(0);
  const [timerTotal, setTimerTotal] = useState(0);
  const [plannedMinutes, setPlannedMinutes] = useState(0);
  const [returnAt, setReturnAt] = useState(0);
  const [techniques, setTechniques] = useState<string[]>([]);
  const [stats, setStats] = useState<Stats>(EMPTY_STATS);

  useEffect(() => {
    const id = window.setTimeout(() => setStats(loadStats()), 0);
    return () => window.clearTimeout(id);
  }, []);

  useEffect(() => {
    if (scene !== "timer" || timer <= 0) return;

    const id = window.setTimeout(() => {
      if (timer <= 1) {
        setTimer(0);
        setPauseSeconds((value) => value + timerTotal);
        setPressure((value) => Math.max(38, value - 24));
        setTechniques((current) =>
          current.includes("フット・イン・ザ・ドア")
            ? current
            : [...current, "フット・イン・ザ・ドア"],
        );
        buzz([20, 40, 20]);
        setScene("purpose");
        return;
      }
      setTimer((value) => Math.max(0, value - 1));
    }, 1000);

    return () => window.clearTimeout(id);
  }, [scene, timer, timerTotal]);

  const returnTime = returnAt
    ? new Intl.DateTimeFormat("ja-JP", {
        hour: "2-digit",
        minute: "2-digit",
      }).format(new Date(returnAt))
    : "";

  function addTechnique(name: string) {
    setTechniques((current) => (current.includes(name) ? current : [...current, name]));
  }

  function soften(amount: number, technique?: string) {
    setPressure((value) => Math.max(12, value - amount));
    if (technique) addTechnique(technique);
    buzz();
  }

  function saveSession(avoidedNowSend: boolean, didPause: boolean) {
    const previous = loadStats();
    const next: Stats = {
      sessions: previous.sessions + 1,
      pauses: previous.pauses + (didPause ? 1 : 0),
      avoidedNowSend: previous.avoidedNowSend + (avoidedNowSend ? 1 : 0),
    };
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
    } catch {
      // Persistence is optional; the negotiation itself still works.
    }
    setStats(next);
  }

  function startTimer(seconds: number) {
    setTimerTotal(seconds);
    setTimer(seconds);
    setScene("timer");
    soften(8, "段階的譲歩");
  }

  function finish(minutes: number) {
    setPlannedMinutes(minutes);
    setReturnAt(Date.now() + minutes * 60_000);
    soften(minutes >= 20 ? 32 : 20, "コミットメント");
    saveSession(true, true);
    setScene("finish");
  }

  function sendAnyway() {
    addTechnique("最終選択の明確化");
    saveSession(false, pauseSeconds > 0);
    setScene("send-anyway");
  }

  function reset() {
    setScene("opening");
    setPressure(100);
    setPauseSeconds(0);
    setTimer(0);
    setTimerTotal(0);
    setPlannedMinutes(0);
    setReturnAt(0);
    setTechniques([]);
  }

  const progressLabel = `${100 - pressure}%`;

  return (
    <main className={styles.page}>
      <LevelUpHomeButton />
      <header className={styles.header}>
        <div>
          <p className={styles.series}>NEGOTIATOR / 01</p>
          <h1>怒りの返信をやめろ</h1>
        </div>
        <div className={styles.pressureBox} aria-label={`送信圧 ${pressure}`}>
          <span>送信圧</span>
          <strong>{pressure}</strong>
        </div>
      </header>

      <section className={styles.meterWrap} aria-hidden="true">
        <div className={styles.meterTrack}>
          <div className={styles.meterFill} style={{ width: `${pressure}%` }} />
        </div>
        <div className={styles.meterLabels}>
          <span>冷静</span>
          <span>今すぐ送る</span>
        </div>
      </section>

      <section className={styles.stage}>
        {scene === "opening" && (
          <Conversation
            negotiator="その返信、20分だけ送らないで。"
            sub="消せとは言わない。直せとも言わない。送信だけ20分保留。"
            choices={[
              {
                label: "20分は無理。今返す",
                tone: "resist",
                onClick: () => {
                  soften(4);
                  addTechnique("ドア・イン・ザ・フェイス");
                  setScene("shrink");
                },
              },
              { label: "20秒なら待てる", tone: "middle", onClick: () => startTimer(20) },
              { label: "今日は送らない", tone: "accept", onClick: () => finish(720) },
            ]}
          />
        )}

        {scene === "shrink" && (
          <Conversation
            negotiator="了解。20分は取り下げる。"
            sub="じゃあ20秒だけ。この画面にいて、送信ボタンを押さない。それだけ。"
            note="要求を小さくしました。まだ断ってOK。"
            choices={[
              { label: "20秒なら", tone: "accept", onClick: () => startTimer(20) },
              { label: "5秒なら", tone: "middle", onClick: () => startTimer(5) },
              {
                label: "それすら無理",
                tone: "resist",
                onClick: () => {
                  soften(3);
                  setScene("tiny");
                },
              },
            ]}
          />
        )}

        {scene === "tiny" && (
          <Conversation
            negotiator="では1つだけ。"
            sub="『今すぐ送る』を決めなくていい。5秒だけ決定を保留する。送るかどうかは、その後あなたが決める。"
            choices={[
              { label: "5秒だけ", tone: "accept", onClick: () => startTimer(5) },
              { label: "わかった、20秒", tone: "middle", onClick: () => startTimer(20) },
              {
                label: "それでも今返す",
                tone: "resist",
                onClick: () => {
                  addTechnique("選択の自由を残す");
                  setScene("last");
                },
              },
            ]}
          />
        )}

        {scene === "timer" && (
          <div className={styles.timerCard}>
            <p className={styles.timerEyebrow}>SEND NOTHING</p>
            <div className={styles.timerNumber}>{timer}</div>
            <p>
              文章を考え直さなくていい。
              <br />
              ただ、送らない。
            </p>
            <div className={styles.breathLine} aria-hidden="true" />
          </div>
        )}

        {scene === "purpose" && (
          <Conversation
            negotiator="できた。もう送信は数秒遅れた。"
            sub="ここからは怒りを否定しない。あなたが返信したい一番の目的は？"
            note={`いま作れた間：${pauseSeconds}秒`}
            choices={[
              {
                label: "誤解・間違いを訂正したい",
                tone: "middle",
                onClick: () => {
                  soften(14, "目的の再定義");
                  setScene("correction");
                },
              },
              {
                label: "舐められたくない",
                tone: "resist",
                onClick: () => {
                  soften(10, "ラベリング");
                  setScene("respect");
                },
              },
              {
                label: "とにかく言い返したい",
                tone: "resist",
                onClick: () => {
                  soften(8, "感情の言語化");
                  setScene("discharge");
                },
              },
            ]}
          />
        )}

        {scene === "correction" && (
          <Conversation
            negotiator="なら目的は『訂正』。怒りを全部届けることではない。"
            sub="事実だけ残せば目的は達成できる。返信文は下書きのまま、時間を置いてから事実だけ見直さない？"
            choices={[
              { label: "20分保留する", tone: "accept", onClick: () => finish(20) },
              { label: "5分なら保留する", tone: "middle", onClick: () => finish(5) },
              { label: "いや、今すぐ訂正する", tone: "resist", onClick: () => setScene("last") },
            ]}
          />
        )}

        {scene === "respect" && (
          <Conversation
            negotiator="『即レス＝強さ』とは限らない。"
            sub="相手のペースで反射するより、自分が返す時間を決める方が主導権は残る。返信の主導権、5分だけ取り戻す？"
            choices={[
              { label: "20分、自分の時間にする", tone: "accept", onClick: () => finish(20) },
              { label: "5分だけなら", tone: "middle", onClick: () => finish(5) },
              { label: "強さを見せたいから今返す", tone: "resist", onClick: () => setScene("last") },
            ]}
          />
        )}

        {scene === "discharge" && (
          <div className={styles.dischargeCard}>
            <p className={styles.negotiatorName}>NEGOTIATOR</p>
            <h2>怒りはある。送信先だけ変える。</h2>
            <p>相手にぶつける代わりに、このボタンへ1回だけ捨てる。文章入力は不要。</p>
            <button
              className={styles.dumpButton}
              type="button"
              onClick={() => {
                soften(20, "反応と行動を分離");
                setScene("last");
              }}
            >
              <span>ここに怒りを捨てる</span>
              <b>DON&apos;T SEND →</b>
            </button>
          </div>
        )}

        {scene === "last" && (
          <Conversation
            negotiator="最後の交渉。"
            sub="怒ったまま返す自由は残す。その代わり『今』だけ外す。明日の自分が読んでも同じ文を送りたいなら、その時送ればいい。"
            note="ここまで全部断っても、あなたの決定権は残っています。"
            choices={[
              { label: "20分保留する", tone: "accept", onClick: () => finish(20) },
              { label: "5分だけ保留する", tone: "middle", onClick: () => finish(5) },
              { label: "それでも今送る", tone: "resist", onClick: sendAnyway },
            ]}
          />
        )}

        {scene === "finish" && (
          <ResultCard
            kind="held"
            pressure={pressure}
            pauseSeconds={pauseSeconds}
            plannedMinutes={plannedMinutes}
            returnTime={returnTime}
            techniques={techniques}
            stats={stats}
            onReset={reset}
          />
        )}

        {scene === "send-anyway" && (
          <ResultCard
            kind="send"
            pressure={pressure}
            pauseSeconds={pauseSeconds}
            plannedMinutes={0}
            returnTime=""
            techniques={techniques}
            stats={stats}
            onReset={reset}
          />
        )}
      </section>

      <aside className={styles.log}>
        <span>NEGOTIATION PROGRESS</span>
        <strong>{progressLabel}</strong>
        <p>{techniques.length ? techniques.join(" / ") : "まだ交渉中"}</p>
      </aside>

      <footer className={styles.footer}>
        <span>怒りをなくすゲームではありません。</span>
        <span>怒っている時の「即送信」と自分の間に距離をつくるゲームです。</span>
      </footer>
    </main>
  );
}

type Choice = {
  label: string;
  tone: "resist" | "middle" | "accept";
  onClick: () => void;
};

function Conversation({
  negotiator,
  sub,
  note,
  choices,
}: {
  negotiator: string;
  sub: string;
  note?: string;
  choices: Choice[];
}) {
  return (
    <div className={styles.conversation}>
      <p className={styles.negotiatorName}>NEGOTIATOR</p>
      <h2>{negotiator}</h2>
      <p className={styles.sub}>{sub}</p>
      {note && <p className={styles.note}>{note}</p>}
      <div className={styles.choices}>
        {choices.map((choice) => (
          <button
            key={choice.label}
            className={`${styles.choice} ${styles[choice.tone]}`}
            type="button"
            onClick={choice.onClick}
          >
            {choice.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function ResultCard({
  kind,
  pressure,
  pauseSeconds,
  plannedMinutes,
  returnTime,
  techniques,
  stats,
  onReset,
}: {
  kind: "held" | "send";
  pressure: number;
  pauseSeconds: number;
  plannedMinutes: number;
  returnTime: string;
  techniques: string[];
  stats: Stats;
  onReset: () => void;
}) {
  const held = kind === "held";
  return (
    <div className={`${styles.result} ${held ? styles.resultSafe : styles.resultSend}`}>
      <p className={styles.resultKicker}>{held ? "NEGOTIATION WON" : "NEGOTIATION ENDED"}</p>
      <h2>{held ? "『今すぐ送る』を止めた。" : "送るなら、3つだけ削る。"}</h2>
      {held ? (
        <>
          <p className={styles.resultLead}>
            怒りが消えた必要はありません。送信と怒りの間に、あなたが決めた時間を置けました。
          </p>
          <div className={styles.resultGrid}>
            <div>
              <span>送信圧</span>
              <strong>100 → {pressure}</strong>
            </div>
            <div>
              <span>実際に待った</span>
              <strong>{pauseSeconds}秒</strong>
            </div>
            <div>
              <span>次に見る</span>
              <strong>{plannedMinutes >= 720 ? "明日" : returnTime || "あとで"}</strong>
            </div>
          </div>
          <div className={styles.ruleCard}>
            <span>NEXT RULE</span>
            <strong>戻ったら「目的1つ・事実1つ・要求1つ」だけ残す。</strong>
          </div>
        </>
      ) : (
        <>
          <p className={styles.resultLead}>
            このアプリは送信を禁止しません。今送るなら、攻撃を増やす部分だけ切ってから送る。
          </p>
          <ol className={styles.checks}>
            <li>
              <b>目的を1つ</b>
              <span>訂正・依頼・断る、のどれかにする。</span>
            </li>
            <li>
              <b>侮辱語を消す</b>
              <span>人格ではなく、起きたことを書く。</span>
            </li>
            <li>
              <b>要求を1文</b>
              <span>相手に何をしてほしいかだけ残す。</span>
            </li>
          </ol>
        </>
      )}
      <div className={styles.techniques}>
        <span>今回使われた交渉</span>
        <p>{techniques.length ? techniques.join(" / ") : "選択の明確化"}</p>
      </div>
      <p className={styles.history}>
        これまで {stats.sessions} 回交渉 / 「今すぐ送る」を外した {stats.avoidedNowSend} 回
      </p>
      <div className={styles.resultActions}>
        <button type="button" onClick={onReset}>
          もう一度交渉する
        </button>
        <a href="https://levelup.hitobito.jp/">LEVEL UPへ戻る</a>
      </div>
    </div>
  );
}

.page {
  --bg: #090b0e;
  --panel: #12151a;
  --line: rgba(255,255,255,.11);
  --text: #f6f7f8;
  --muted: #9ea5af;
  --red: #ff5b4d;
  --amber: #ffca5a;
  --lime: #d8ff5b;
  min-height: 100svh;
  background:
    radial-gradient(circle at 85% 8%, rgba(255,91,77,.15), transparent 34%),
    linear-gradient(180deg, #0c0e12 0%, var(--bg) 42%, #070809 100%);
  color: var(--text);
  padding: 22px clamp(18px, 4vw, 54px) 36px;
  font-family: Arial, Helvetica, sans-serif;
}

.header {
  width: min(980px, 100%);
  margin: 0 auto;
  padding: 58px 0 20px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid var(--line);
}

.series {
  margin: 0 0 10px;
  color: var(--red);
  font-size: 12px;
  letter-spacing: .16em;
  font-weight: 900;
}

.header h1 {
  margin: 0;
  font-size: clamp(32px, 7vw, 74px);
  line-height: .96;
  letter-spacing: -.06em;
}

.pressureBox {
  flex: 0 0 auto;
  min-width: 94px;
  padding: 12px 14px;
  border: 1px solid rgba(255,91,77,.35);
  border-radius: 16px;
  background: rgba(255,91,77,.08);
  text-align: right;
}

.pressureBox span {
  display: block;
  color: #ff9d95;
  font-size: 11px;
  font-weight: 800;
}

.pressureBox strong {
  display: block;
  margin-top: 2px;
  color: #fff;
  font-size: 32px;
  line-height: 1;
}

.meterWrap {
  width: min(980px, 100%);
  margin: 18px auto 0;
}

.meterTrack {
  height: 9px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255,255,255,.08);
}

.meterFill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--lime), var(--amber) 52%, var(--red));
  transition: width .45s cubic-bezier(.2,.8,.2,1);
}

.meterLabels {
  display: flex;
  justify-content: space-between;
  margin-top: 7px;
  color: #777f89;
  font-size: 11px;
  font-weight: 800;
}

.stage {
  width: min(780px, 100%);
  min-height: 470px;
  margin: 34px auto 0;
  display: grid;
  align-items: center;
}

.conversation,
.timerCard,
.dischargeCard,
.result {
  border: 1px solid var(--line);
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(22,25,31,.96), rgba(14,16,20,.98));
  box-shadow: 0 28px 80px rgba(0,0,0,.34);
}

.conversation {
  padding: clamp(24px, 5vw, 48px);
}

.negotiatorName,
.timerEyebrow,
.resultKicker {
  margin: 0 0 16px;
  color: var(--lime);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: .18em;
}

.conversation h2,
.dischargeCard h2,
.result h2 {
  margin: 0;
  font-size: clamp(28px, 5.4vw, 48px);
  line-height: 1.05;
  letter-spacing: -.045em;
}

.sub,
.dischargeCard > p:not(.negotiatorName),
.resultLead {
  margin: 20px 0 0;
  color: #c9ced5;
  font-size: clamp(15px, 2.2vw, 18px);
  line-height: 1.8;
}

.note {
  margin: 18px 0 0;
  padding: 11px 13px;
  border-left: 3px solid var(--amber);
  background: rgba(255,202,90,.06);
  color: #e8d8ae;
  font-size: 12px;
  line-height: 1.6;
}

.choices {
  display: grid;
  gap: 10px;
  margin-top: 32px;
}

.choice,
.resultActions button,
.resultActions a {
  min-height: 58px;
  border-radius: 16px;
  border: 1px solid var(--line);
  font: inherit;
  font-weight: 900;
  cursor: pointer;
  transition: transform .12s ease, border-color .12s ease, background .12s ease;
  -webkit-tap-highlight-color: transparent;
}

.choice:hover,
.resultActions button:hover,
.resultActions a:hover {
  transform: translateY(-1px);
}

.choice:active,
.resultActions button:active {
  transform: translateY(1px) scale(.995);
}

.resist {
  background: rgba(255,91,77,.08);
  color: #ffd1cd;
  border-color: rgba(255,91,77,.26);
}

.middle {
  background: rgba(255,202,90,.07);
  color: #ffe5a6;
  border-color: rgba(255,202,90,.25);
}

.accept {
  background: rgba(216,255,91,.10);
  color: #edffb7;
  border-color: rgba(216,255,91,.32);
}

.timerCard {
  padding: 42px 24px 48px;
  text-align: center;
}

.timerNumber {
  font-size: clamp(100px, 27vw, 210px);
  line-height: .8;
  letter-spacing: -.08em;
  font-weight: 950;
  color: #fff;
}

.timerCard > p:not(.timerEyebrow) {
  margin: 28px 0 0;
  color: #aeb5be;
  line-height: 1.7;
}

.breathLine {
  width: 54%;
  height: 4px;
  margin: 34px auto 0;
  border-radius: 999px;
  background: var(--lime);
  animation: breathe 2s ease-in-out infinite;
  transform-origin: center;
}

@keyframes breathe {
  0%,100% { transform: scaleX(.45); opacity: .4; }
  50% { transform: scaleX(1); opacity: 1; }
}

.dischargeCard {
  padding: clamp(26px, 5vw, 46px);
}

.dumpButton {
  width: 100%;
  min-height: 122px;
  margin-top: 30px;
  border: 1px solid rgba(255,91,77,.42);
  border-radius: 22px;
  background:
    repeating-linear-gradient(-45deg, rgba(255,91,77,.08) 0 10px, rgba(255,91,77,.03) 10px 20px),
    #171216;
  color: #fff;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.dumpButton span {
  font-size: 22px;
  font-weight: 950;
}

.dumpButton b {
  color: #ff8f86;
  font-size: 11px;
  letter-spacing: .14em;
}

.result {
  padding: clamp(26px, 5vw, 46px);
}

.resultSafe {
  border-color: rgba(216,255,91,.28);
  box-shadow: 0 28px 80px rgba(130,170,0,.08), 0 28px 80px rgba(0,0,0,.34);
}

.resultSend {
  border-color: rgba(255,202,90,.25);
}

.resultGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 28px;
}

.resultGrid > div {
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255,255,255,.025);
}

.resultGrid span,
.techniques > span,
.ruleCard > span {
  display: block;
  color: #818995;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .08em;
}

.resultGrid strong {
  display: block;
  margin-top: 8px;
  font-size: 20px;
}

.ruleCard {
  margin-top: 14px;
  padding: 17px;
  border-radius: 16px;
  background: rgba(216,255,91,.08);
  border: 1px solid rgba(216,255,91,.22);
}

.ruleCard strong {
  display: block;
  margin-top: 8px;
  color: #efffc1;
  line-height: 1.55;
}

.checks {
  margin: 26px 0 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 10px;
}

.checks li {
  padding: 16px 17px;
  border: 1px solid var(--line);
  border-radius: 16px;
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 12px;
  align-items: baseline;
}

.checks b { color: #ffe096; }
.checks span { color: #b1b7bf; line-height: 1.6; }

.techniques {
  margin-top: 22px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
}

.techniques p {
  margin: 8px 0 0;
  color: #b7bec7;
  font-size: 12px;
  line-height: 1.65;
}

.history {
  margin: 16px 0 0;
  color: #727a84;
  font-size: 12px;
}

.resultActions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 24px;
}

.resultActions button,
.resultActions a {
  display: grid;
  place-items: center;
  text-align: center;
  text-decoration: none;
  background: #f4f6f7;
  color: #0c0e11;
}

.resultActions a {
  background: transparent;
  color: #ced4db;
}

.log {
  width: min(780px, 100%);
  margin: 18px auto 0;
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255,255,255,.02);
  display: grid;
  grid-template-columns: auto auto 1fr;
  gap: 14px;
  align-items: center;
}

.log > span {
  color: #69717b;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .12em;
}

.log > strong {
  color: var(--lime);
  font-size: 13px;
}

.log p {
  margin: 0;
  color: #858d97;
  font-size: 10px;
  text-align: right;
}

.footer {
  width: min(780px, 100%);
  margin: 18px auto 0;
  padding: 16px 4px 0;
  color: #656d77;
  font-size: 11px;
  line-height: 1.7;
  display: flex;
  justify-content: space-between;
  gap: 18px;
}

@media (max-width: 620px) {
  .page { padding-left: 14px; padding-right: 14px; }
  .header { padding-top: 62px; align-items: flex-end; }
  .header h1 { max-width: 260px; }
  .pressureBox { min-width: 78px; padding: 10px 11px; }
  .pressureBox strong { font-size: 28px; }
  .stage { min-height: 520px; margin-top: 22px; }
  .conversation, .timerCard, .dischargeCard, .result { border-radius: 22px; }
  .conversation { padding: 24px 18px; }
  .choice { min-height: 62px; padding: 10px 14px; }
  .resultGrid { grid-template-columns: 1fr; }
  .checks li { grid-template-columns: 1fr; gap: 5px; }
  .resultActions { grid-template-columns: 1fr; }
  .log { grid-template-columns: auto auto; }
  .log p { grid-column: 1 / -1; text-align: left; }
  .footer { display: block; }
  .footer span { display: block; }
}

@media (prefers-reduced-motion: reduce) {
  .meterFill, .choice, .resultActions button, .resultActions a { transition: none; }
  .breathLine { animation: none; }
}

