  .lead { font-size: 15px; }
  .splitPreview { grid-template-columns: 1fr; margin-top: 30px; }
  .previewArrow { min-height: 24px; transform: rotate(90deg); }
  .previewAnti, .previewVision { min-height: 94px; }
  .heroButton { display: grid; gap: 6px; justify-items: start; }
  .workScreen, .checkinScreen, .nightScreen, .doneScreen { padding: 36px 0 56px; }
  .question { font-size: 34px; }
  .answerBox { font-size: 16px; min-height: 180px; }
  .workActions { grid-template-columns: 92px minmax(0, 1fr); }
  .directionGrid { grid-template-columns: 1fr; }
  .directionButton { min-height: 78px; }
  .dualAnswer { grid-template-columns: 1fr; }
  .nightGrid { grid-template-columns: 1fr; }
  .tomorrowField { grid-column: auto; }
  .dashboardHero { align-items: center; padding-top: 40px; }
  .dashboardHero h1 { font-size: 40px; }
  .progressOrb { width: 96px; }
  .progressOrb span { font-size: 24px; }
  .morningStatus, .nightCallout, .sectionHead { align-items: stretch; flex-direction: column; }
  .morningStatus .secondaryButton, .nightCallout .primaryButton, .calendarButton { width: 100%; }
  .timelineItem { grid-template-columns: 64px 18px minmax(0, 1fr); gap: 9px; min-height: 88px; }
  .timelineTime { font-size: 18px; }
  .timelineAction { display: none; }
  .futureSplit { grid-template-columns: 1fr; }
  .doneStats { grid-template-columns: 1fr 1fr 1fr; }
  .doneStats span { padding: 12px 10px; }
  .doneStats strong { font-size: 22px; }
  .doneActions { grid-template-columns: 1fr; }
  .footer { flex-direction: column; line-height: 1.7; }
}

@media (prefers-reduced-motion: reduce) {
  .page *, .page *::before, .page *::after { scroll-behavior: auto !important; transition: none !important; }
}

